} }];

// WF-50: Prepare WhatsApp message payload (pseudocode Step 2 + Step 3 guard).
// Handles text / interactive / template. The TD-033 guard now covers all three
// messageType paths and never silently drops — it sets __drop=true so the
// downstream branch can log to WF-60 and return a structured error to the caller.

const input = $input.first().json;

const phoneNumber = input.phoneNumber || input.phoneNumberFormatted;
const messageType = input.messageType || 'text';
const messageContent = input.messageContent ?? null;
const interactivePayload = input.interactivePayload || null;
const templateName = input.templateName || null;
const templateParams = input.templateParams || [];
const consultationId = input.consultationId || input.user?.current_consultation_id || null;
const userId = input.userId || input.user?.id || null;

// Step 3 guard — detect missing/empty body per messageType
let drop = false;
if (messageType === 'text') {
  if (!messageContent || String(messageContent).trim().length === 0) drop = true;
} else if (messageType === 'interactive') {
  if (!interactivePayload) {
    drop = true;
  } else {
    const t = interactivePayload.type;
    if (t !== 'flow' && t !== 'button') {
      drop = true;
    } else if (t === 'flow' && (!interactivePayload.flowId || String(interactivePayload.flowId).trim() === '')) {
      drop = true;
    } else if (t === 'button' && (!interactivePayload.action || !Array.isArray(interactivePayload.action.buttons) || interactivePayload.action.buttons.length === 0)) {
      drop = true;
    }
  }
} else if (messageType === 'template') {
  if (!templateName || String(templateName).trim() === '') drop = true;
}

return [{
  json: {
    phoneNumber,
    phoneNumberFormatted: input.phoneNumber,
    messageType,
    messageContent,
    interactivePayload,
    templateName,
    templateParams,
    consultationId,
    userId,
    inboundMessageId: input.inboundMessageId || null,
    userMessage: input.userMessage || null,
    __drop: drop
  }
}];

// Process send result and prepare for logging
const prepareData = $('Prepare Payload').first().json;
const sendResult = $input.first().json;

let success = false;
let messageId = null;
let error = null;

// Check WhatsApp API response
if (sendResult.messages && sendResult.messages[0]) {
  success = true;
  messageId = sendResult.messages[0].id;
} else if (sendResult.error) {
  error = sendResult.error.message || JSON.stringify(sendResult.error);
} else {
  // Fallback for unexpected response format
  success = true;
  messageId = 'unknown';
}

return [{ json: {
  // Message delivery status
  success: success,
  messageId: messageId,
  error: error,

  // Message details
  phoneNumber: prepareData.phoneNumber,
  messageType: prepareData.messageType,
  messageContent: prepareData.messageContent,

  // Context for logging
  userId: prepareData.userId,
  inboundMessageId: prepareData.inboundMessageId,
  userMessage: prepareData.userMessage,

  // Timestamp
  sentAt: new Date().toISOString()
} }];

const input = $input.item.json;
const interactiveType = input.interactivePayload.type; // 'flow' or 'button'

if (interactiveType === 'flow') {
  // Flow type (your existing form logic)
  return [{ json: {
    messaging_product: "whatsapp",
    recipient_type: "individual",
    to: input.phoneNumber,
    type: "interactive",
    interactive: {
      type: "flow",
      header: {
        type: "text",
        text: input.interactivePayload.header.text
      },
      body: {
        text: input.interactivePayload.body.text
      },
      footer: {
        text: "Tap below to continue"
      },
      action: {
        name: "flow",
        parameters: {
          flow_message_version: "3",
          // flow_token: `${input.userId}_${Date.now()}`,
          flow_token: `${Date.now()}`,
          flow_id: input.interactivePayload.flowId,
          flow_cta: input.interactivePayload.flowCta,
          flow_action: "navigate"
        }
      }
    }
  } }];
} else if (interactiveType === 'button') {
  // Button type (payment confirmation, etc.)
  return [{ json: {
    messaging_product: "whatsapp",
    recipient_type: "individual",
    to: input.phoneNumber,
    type: "interactive",
    interactive: {
      type: "button",
      body: {
        text: input.interactivePayload.body.text
      },
      action: {
        buttons: input.interactivePayload.action.buttons
      }
    }
  } }];
}

const input = $input.item.json;

const components = [];
if (input.templateParams && input.templateParams.length > 0) {
  components.push({
    type: 'body',
    parameters: input.templateParams.map(p => ({ type: 'text', text: String(p) }))
  });
}

return [{ json: {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: input.phoneNumber,
  type: 'template',
  template: {
    name: input.templateName,
    language: { code: 'en' },
    components: components
  }
} }];

// Pseudocode Step 12 (drop branch) — structured error returned to caller.
const prep = $('Prepare Payload').first().json;
return [{
  json: {
    success: false,
    messageId: null,
    error: 'empty_body_dropped',
    phoneNumber: prep?.phoneNumber || null,
    sentAt: new Date().toISOString()
  }
}];

// WF-50 → WF-60 canonical shape (outbound success/error path).
// Per-messageType content extraction (TD-F, 2026-05-21):
//   text       → prep.messageContent
//   interactive→ prep.interactivePayload.body.text || JSON.stringify(interactivePayload)
//   template   → 'template:' + (prep.templateName ?? '')
// Metadata is enriched with buttons (interactive) or templateParams (template).
const prep = $('Prepare Payload').first().json;
const result = $input.first().json;
const messageType = prep.messageType || 'text';

let content;
if (messageType === 'text') {
  content = prep.messageContent ?? null;
} else if (messageType === 'interactive') {
  content = prep?.interactivePayload?.body?.text
    || (prep?.interactivePayload ? JSON.stringify(prep.interactivePayload) : null);
} else if (messageType === 'template') {
  content = 'template:' + (prep?.templateName ?? '');
} else {
  content = prep.messageContent ?? null;
}

const metadata = {
  success: result.success ?? null,
  error: result.error ?? null,
  sentAt: result.sentAt ?? null,
  inboundMessageId: prep.inboundMessageId ?? null
};
if (messageType === 'interactive' && Array.isArray(prep?.interactivePayload?.action?.buttons)) {
  metadata.buttons = prep.interactivePayload.action.buttons.map(b => ({ id: b.id, title: b.title }));
}
if (messageType === 'template' && prep?.templateParams != null) {
  metadata.templateParams = prep.templateParams;
}

return [{
  json: {
    transport: 'wa',
    direction: 'outbound',
    userId: prep.userId ?? null,
    consultationId: prep.consultationId ?? null,
    messageType,
    content,
    whatsappMessageId: result.messageId ?? null,
    phoneNumber: prep.phoneNumber ?? prep.phoneNumberFormatted ?? null,
    metadata
  }
}];

