    messageType,
    content,
    whatsappMessageId: null,
    phoneNumber: prep.phoneNumber ?? prep.phoneNumberFormatted ?? null,
    metadata
  }
}];

// WF-50 entry guard — §2.3 discriminated-union input contract.
// Throws on any contract violation so callers get an immediate, named error
// rather than a silent drop or malformed WhatsApp payload.
const i = $input.first().json;

if (!i.phoneNumber || typeof i.phoneNumber !== 'string')
  throw new Error('WF-50 contract: phoneNumber required (E.164 string)');

if (!['text', 'interactive', 'template'].includes(i.messageType))
  throw new Error('WF-50 contract: messageType must be text|interactive|template, got: ' + i.messageType);

if (i.messageType === 'text' && (!i.messageContent || typeof i.messageContent !== 'string'))
  throw new Error('WF-50 contract: text variant requires non-empty messageContent');

if (i.messageType === 'interactive' && (!i.interactivePayload || typeof i.interactivePayload !== 'object'))
  throw new Error('WF-50 contract: interactive variant requires interactivePayload object');

if (i.messageType === 'template' && (!i.templateName || !Array.isArray(i.templateParams)))
  throw new Error('WF-50 contract: template variant requires templateName + templateParams[]');

// Reject deprecated fallback keys — callers must use messageContent, not message/messageBody.
if (!i.messageContent && (i.message || i.messageBody))
  throw new Error('WF-50 contract: use messageContent (not message/messageBody) — deprecated fallback keys removed');

return [{ json: i }];

// Return final status to calling workflow
const result = $('Process Result').first().json;

return [{ json: {
  success: result.success,
  messageId: result.messageId,
  error: result.error,
  phoneNumber: result.phoneNumber,
  sentAt: result.sentAt
} }];

